import DesignSystem
import SwiftUI

// Boards E0 (Compare, no videos yet) and F0 (Queue, no videos yet), generated by
// ds/compare_empty.py and ds/queue_empty.py: steps 1 and 2 small, in outline, in
// one frame; step 3 large; the drop area of Start at the bottom. Adding videos
// from either page takes you to the Queue.
//
// Nothing here stretches: the block keeps the board's sizes and is centred in
// the page. It has three widths (`EmptyLayout`), the widest that fits is used,
// and the page scrolls when the window is too low for it.

struct CompareEmptyView<Header: View>: View {
    @Environment(AppModel.self) private var model
    /// Board E0c: videos added, none analysed yet. A note with the progress above
    /// the steps, and the drop area takes more of them.
    var analysing = false
    @ViewBuilder var header: Header

    var body: some View {
        EmptyPage(header: VStack(alignment: .leading, spacing: 16) {
                      header
                      if analysing { AnalysingNote() }
                  },
                  drop: model.t(analysing ? "nat.empty.drop_more_text" : "nat.empty.cmp_drop_text"),
                  dropTitle: analysing ? model.t("nat.empty.drop_more") : nil) { layout in
            EmptyStepsFrame(model.t("nat.empty.before_test"), layout: layout) {
                EmptyStep(1, model.t("nat.empty.clips"), model.t("nat.empty.clips_text")) { FilmOutline() }
            } second: {
                EmptyStep(2, model.t("nat.empty.models"), model.t("nat.empty.models_text")) { ModelsOutline() }
            }
        } result: { layout in
            EmptyFrame(numbered: 3, model.t("nat.empty.results"), hint: model.t("nat.empty.results_hint")) {
                HStack(alignment: .top, spacing: 16) {
                    VStack(spacing: 10) {
                        SplitIllustration(left: model.t("nat.cmp.original"), right: model.t("mot.modello.cugan.label"))
                            .aspectRatio(16 / 9, contentMode: .fit)
                        PlayBarIllustration()
                    }
                    // Only the widest block has room for it. As tall as the player:
                    // the cards below fade out instead of making the frame taller.
                    if layout == .wide {
                        Color.clear.frame(width: 220)
                            .overlay(alignment: .top) { TestedModelsIllustration() }
                            .clipped()
                    }
                }
            }
        }
    }
}

struct QueueEmptyView<Header: View>: View {
    @Environment(AppModel.self) private var model
    @ViewBuilder var header: Header

    var body: some View {
        EmptyPage(header: header, drop: model.t("nat.empty.queue_drop_text")) { layout in
            EmptyStepsFrame(model.t("nat.empty.before_start"), layout: layout) {
                EmptyStep(1, model.t("nat.empty.analysed"), model.t("nat.empty.analysed_text")) { AnalysisOutline() }
            } second: {
                EmptyStep(2, model.t("nat.empty.model_each"), model.t("nat.empty.model_each_text")) { ModelRowsOutline() }
            }
        } result: { _ in
            EmptyFrame(numbered: 3, model.t("nat.empty.chunks"), hint: model.t("nat.empty.chunks_hint")) {
                VStack(alignment: .leading, spacing: 12) {
                    Spacer(minLength: 0)
                    QueueRowsIllustration()
                    Color.clear.frame(height: 4)
                    infoLine(model.t("nat.empty.carried")) {
                        HStack(spacing: 8) {
                            ForEach(["nat.empty.audio", "nat.empty.subtitles", "nat.empty.chapters"], id: \.self) {
                                StatusChip(model.t($0), tone: .green, symbol: "checkmark")
                            }
                        }
                    } text: { Text(model.t("nat.empty.merged")) }
                    infoLine(model.t("nat.empty.background")) {
                        Image(systemName: "bell.badge")
                    } text: { Text(model.t("nat.empty.background_text")) }
                    Spacer(minLength: 0)
                }
            }
        }
    }

    /// Label, marks and text on one line; the text goes under the marks when it doesn't fit.
    private func infoLine(_ label: String, @ViewBuilder marks: () -> some View, @ViewBuilder text: () -> Text) -> some View {
        let marks = marks().auFont(12).foregroundStyle(AU.text2)
        let text = text().auFont(12).foregroundStyle(AU.text2)
        return HStack(alignment: .firstTextBaseline, spacing: 8) {
            Text(label).auLabel().frame(width: 118, alignment: .leading)
            ViewThatFits(in: .horizontal) {
                HStack(spacing: 8) { marks; text.fixedSize() }
                VStack(alignment: .leading, spacing: 6) { marks; text.fixedSize(horizontal: false, vertical: true) }
            }
        }
    }
}

// MARK: - Page

/// The block's three widths. Wide is the board: steps 1–2 (250) · arrow · step 3
/// with the 499 × 281 player and the tested models. Medium drops the models.
/// Stacked puts steps 1–2 side by side above step 3.
enum EmptyLayout: CaseIterable {
    case wide, medium, stacked

    var width: CGFloat {
        switch self {
        case .wide: 1060
        case .medium: 824
        case .stacked: 560
        }
    }

    static func fitting(_ width: CGFloat) -> EmptyLayout {
        allCases.first { $0.width <= width } ?? .stacked
    }
}

/// The page's header, then the steps and the drop area at the layout's width,
/// centred. When the window is tall enough the steps sit in the middle of the
/// room left above the drop area (as on the boards); otherwise the whole page,
/// header included, scrolls.
private struct EmptyPage<Header: View, Steps: View, Result: View>: View {
    var header: Header
    var drop: String
    var dropTitle: String? = nil
    @ViewBuilder var steps: (EmptyLayout) -> Steps
    @ViewBuilder var result: (EmptyLayout) -> Result
    @Environment(\.auPageTop) private var pageTop
    @State private var layout = EmptyLayout.wide

    var body: some View {
        ViewThatFits(in: .vertical) {
            VStack(alignment: .leading, spacing: 16) {
                header
                VStack(spacing: 0) {
                    Spacer(minLength: 16)
                    row
                    Spacer(minLength: 16)
                    EmptyDrop(text: drop, layout: layout, title: dropTitle)
                }
                .frame(width: layout.width)
                .frame(maxWidth: .infinity)
            }
            .padding(page)
            ScrollView {
                VStack(alignment: .leading, spacing: 16) {
                    header
                    VStack(spacing: 16) {
                        row
                        EmptyDrop(text: drop, layout: layout, title: dropTitle)
                    }
                    .frame(width: layout.width)
                    .padding(.top, 8)
                    .frame(maxWidth: .infinity)
                }
                .padding(page)
            }
            .scrollIndicators(.automatic)
        }
        .frame(minWidth: 0, maxWidth: .infinity, minHeight: 0, maxHeight: .infinity)
        .onGeometryChange(for: EmptyLayout.self) { EmptyLayout.fitting($0.size.width - 56) } action: { layout = $0 }
    }

    /// `.main`: 28 at the sides and at the bottom; the top from the frame.
    private var page: EdgeInsets { EdgeInsets(top: pageTop, leading: 28, bottom: 28, trailing: 28) }

    private var row: some View {
        Group {
            if layout == .stacked {
                VStack(spacing: 10) {
                    steps(layout).fixedSize(horizontal: false, vertical: true)
                    Image(systemName: "arrow.down").auFont(13).foregroundStyle(AU.text3)
                    result(layout).fixedSize(horizontal: false, vertical: true)
                }
            } else {
                HStack(spacing: 14) {
                    steps(layout).frame(width: 250)
                    Image(systemName: "arrow.right").auFont(13).foregroundStyle(AU.text3)
                    result(layout)
                }
                .fixedSize(horizontal: false, vertical: true)
            }
        }
    }
}

// MARK: - Frame

/// "Before the test": steps 1 and 2 one above the other, or side by side when stacked.
private struct EmptyStepsFrame<First: View, Second: View>: View {
    var title: String
    var layout: EmptyLayout
    @ViewBuilder var first: First
    @ViewBuilder var second: Second

    init(_ title: String, layout: EmptyLayout, @ViewBuilder first: () -> First, @ViewBuilder second: () -> Second) {
        self.title = title
        self.layout = layout
        self.first = first()
        self.second = second()
    }

    var body: some View {
        EmptyFrame(title) {
            if layout == .stacked {
                HStack(alignment: .top, spacing: 0) {
                    first.frame(maxWidth: .infinity, alignment: .leading)
                    Rectangle().fill(AU.line).frame(width: 1).padding(.horizontal, 16)
                    second.frame(maxWidth: .infinity, alignment: .leading)
                }
            } else {
                first
                Rectangle().fill(AU.line).frame(height: 1).padding(.vertical, 10)
                second
            }
        }
    }
}

private struct EmptyFrame<Content: View>: View {
    var number: Int?
    var title: String
    var hint: String?
    @ViewBuilder var content: Content

    init(_ title: String, @ViewBuilder content: () -> Content) {
        self.title = title
        self.content = content()
    }

    init(numbered: Int, _ title: String, hint: String, @ViewBuilder content: () -> Content) {
        self.number = numbered
        self.title = title
        self.hint = hint
        self.content = content()
    }

    var body: some View {
        VStack(alignment: .leading, spacing: 12) {
            HStack(spacing: 8) {
                if let number { StepNumber(number) }
                Text(title).auFont(13, .semibold).foregroundStyle(AU.text)
                if let hint { Text(hint).auSmall().lineLimit(1) }
            }
            .frame(height: 22)
            content
        }
        .frame(maxWidth: .infinity, maxHeight: .infinity, alignment: .topLeading)
        .auBox(RoundedRectangle(cornerRadius: 12), fill: AU.surface, line: AU.line,
               padding: EdgeInsets(top: 14, leading: 16, bottom: 16, trailing: 16))
    }
}

/// One step: number and title, the drawing at the board's 218 pt, the text.
/// In the tall steps frame the spare height goes around each step, as on the boards.
private struct EmptyStep<Drawing: View>: View {
    var number: Int
    var title: String
    var text: String
    @ViewBuilder var drawing: Drawing

    init(_ number: Int, _ title: String, _ text: String, @ViewBuilder drawing: () -> Drawing) {
        self.number = number
        self.title = title
        self.text = text
        self.drawing = drawing()
    }

    var body: some View {
        VStack(alignment: .leading, spacing: 12) {
            HStack(spacing: 8) {
                StepNumber(number)
                Text(title).auFont(13, .semibold).foregroundStyle(AU.text)
            }
            drawing.frame(width: 218)
            Text(text).auSmall().frame(maxWidth: 218, alignment: .leading).fixedSize(horizontal: false, vertical: true)
        }
        .frame(maxHeight: .infinity)
    }
}

/// The 22 pt numbered circle of the steps (`.num` on the boards).
private struct StepNumber: View {
    var n: Int
    init(_ n: Int) { self.n = n }
    var body: some View {
        Text("\(n)").auFont(11, .semibold, mono: true).foregroundStyle(AU.text2)
            .frame(width: 22, height: 22)
            .background(Circle().fill(AU.raised))
            .overlay(Circle().strokeBorder(AU.chipLine))
    }
}

private struct EmptyDrop: View {
    @Environment(AppModel.self) private var model
    var text: String
    var layout: EmptyLayout
    /// "Drop more videos…" when some are already there.
    var title: String? = nil

    var body: some View {
        // Stacked, the text beside the cards would wrap word by word: everything goes in a column.
        DropZone(title: title ?? model.t("nat.add.drop"), buttonTitle: model.t("nat.add.open"), primary: true,
                 axis: layout == .stacked ? .vertical : .horizontal, text: text,
                 onOpen: { model.openVideos() },
                 onDrop: { model.add($0) })
            .frame(minHeight: 150)
            .fixedSize(horizontal: false, vertical: true)
    }
}

// MARK: - Outline drawings (1.25 pt strokes, the chosen parts in the accent)

private let outlineStroke = StrokeStyle(lineWidth: 1.25, lineCap: .round, lineJoin: .round)

/// A film strip, nine frames, two picked.
private struct FilmOutline: View {
    var body: some View {
        Canvas { ctx, size in
            let u = size.width / 200
            let strip = CGRect(x: 1, y: 1, width: 198, height: 42).scaled(u)
            ctx.stroke(Path(roundedRect: strip, cornerRadius: 4 * u), with: .color(AU.text3), style: outlineStroke)
            for i in 0..<20 {
                for y in [4.0, 37.5] {
                    ctx.fill(Path(roundedRect: CGRect(x: 6 + Double(i) * 9.4, y: y, width: 4, height: 2.5).scaled(u), cornerRadius: 0.8 * u),
                             with: .color(AU.text3.opacity(0.7)))
                }
            }
            let fw = (200 - 10 - 8 * 4) / 9.0
            for i in 0..<9 {
                let r = Path(roundedRect: CGRect(x: 5 + Double(i) * (fw + 4), y: 10, width: fw, height: 24).scaled(u), cornerRadius: 1.5 * u)
                if i == 2 || i == 6 {
                    ctx.fill(r, with: .color(AU.sel))
                    ctx.stroke(r, with: .color(AU.primary), style: StrokeStyle(lineWidth: 1.5))
                } else {
                    ctx.stroke(r, with: .color(AU.text3), style: outlineStroke)
                }
            }
        }
        .aspectRatio(200 / 44, contentMode: .fit)
    }
}

/// Six versions of one frame, two picked.
private struct ModelsOutline: View {
    var body: some View {
        Canvas { ctx, size in
            let u = size.width / 200
            let cw = (200 - 2 - 12) / 3.0, ch = 27.0
            for i in 0..<6 {
                let x = 1 + Double(i % 3) * (cw + 6), y = 1 + Double(i / 3) * (ch + 6)
                let on = i == 1 || i == 5
                let r = Path(roundedRect: CGRect(x: x, y: y, width: cw, height: ch).scaled(u), cornerRadius: 3 * u)
                if on { ctx.fill(r, with: .color(AU.sel)) }
                ctx.stroke(r, with: .color(on ? AU.primary : AU.text3), style: StrokeStyle(lineWidth: on ? 1.5 : 1.25))
                var hills = Path()
                hills.move(to: CGPoint(x: (x + 7) * u, y: (y + ch - 6) * u))
                for (dx, dy) in [(14.0, -9.0), (10, 6), (14, -10), (12, 13)] {
                    let p = hills.currentPoint!
                    hills.addLine(to: CGPoint(x: p.x + dx * u, y: p.y + dy * u))
                }
                ctx.stroke(hills, with: .color(on ? AU.primary : AU.text3), style: outlineStroke)
            }
        }
        .aspectRatio(200 / 62, contentMode: .fit)
    }
}

/// Two file rows, the first being analysed: chips, one of them a warning.
private struct AnalysisOutline: View {
    var body: some View {
        Canvas { ctx, size in
            let u = size.width / 200
            ctx.fill(Path(roundedRect: CGRect(x: 1, y: 2, width: 120, height: 19).scaled(u), cornerRadius: 3 * u), with: .color(AU.sel.opacity(0.8)))
            for (i, y) in [2.0, 24].enumerated() {
                let on = i == 0
                let line = on ? AU.primary : AU.text3
                ctx.stroke(Path(roundedRect: CGRect(x: 1, y: y, width: 198, height: 19).scaled(u), cornerRadius: 3 * u),
                           with: .color(line), style: StrokeStyle(lineWidth: on ? 1.5 : 1.25))
                ctx.stroke(Path(roundedRect: CGRect(x: 8, y: y + 5, width: 9, height: 9).scaled(u), cornerRadius: 2 * u),
                           with: .color(line), style: outlineStroke)
                for (x, w) in [(23.0, 62.0), (23, 40)] {
                    let yy = y + (w == 62 ? 5 : 11)
                    ctx.fill(Path(roundedRect: CGRect(x: x, y: yy, width: w, height: 3).scaled(u), cornerRadius: 1.5 * u),
                             with: .color(AU.text3.opacity(0.55)))
                }
                for k in 0..<3 {
                    let c = on && k == 2 ? AU.yellowText : line
                    ctx.stroke(Path(roundedRect: CGRect(x: 112 + Double(k) * 29, y: y + 5, width: 25, height: 9).scaled(u), cornerRadius: 4.5 * u),
                               with: .color(c), style: outlineStroke)
                }
            }
        }
        .aspectRatio(200 / 45, contentMode: .fit)
    }
}

/// Three rows, each with its model menu; the middle one chosen.
private struct ModelRowsOutline: View {
    var body: some View {
        Canvas { ctx, size in
            let u = size.width / 200
            for i in 0..<3 {
                let y = 1 + Double(i) * 15, on = i == 1
                let line = on ? AU.primary : AU.text3
                ctx.stroke(Path(roundedRect: CGRect(x: 1, y: y, width: 198, height: 12).scaled(u), cornerRadius: 3 * u),
                           with: .color(line), style: StrokeStyle(lineWidth: on ? 1.5 : 1.25))
                ctx.fill(Path(roundedRect: CGRect(x: 8, y: y + 4.5, width: 56, height: 3).scaled(u), cornerRadius: 1.5 * u),
                         with: .color(AU.text3.opacity(0.55)))
                ctx.stroke(Path(roundedRect: CGRect(x: 128, y: y + 2, width: 64, height: 8).scaled(u), cornerRadius: 2.5 * u),
                           with: .color(line), style: outlineStroke)
                var chevron = Path()
                chevron.move(to: CGPoint(x: 181 * u, y: (y + 5) * u))
                chevron.addLine(to: CGPoint(x: 184 * u, y: (y + 7.5) * u))
                chevron.addLine(to: CGPoint(x: 187 * u, y: (y + 5) * u))
                ctx.stroke(chevron, with: .color(line), style: outlineStroke)
            }
        }
        .aspectRatio(200 / 46, contentMode: .fit)
    }
}

private extension CGRect {
    func scaled(_ u: CGFloat) -> CGRect { CGRect(x: minX * u, y: minY * u, width: width * u, height: height * u) }
}

// MARK: - Step 3, Compare

/// The split player as a picture: the same scene blurred on the left (the original,
/// enlarged) and sharp on the right, the line sweeping slowly between 30% and 70%.
private struct SplitIllustration: View {
    var left: String
    var right: String

    var body: some View {
        TimelineView(.animation) { tl in
            let t = tl.date.timeIntervalSinceReferenceDate
            let split = 0.5 - 0.2 * cos(t * .pi / 3)
            GeometryReader { g in
                let x = g.size.width * split
                ZStack(alignment: .topLeading) {
                    SceneArt().blur(radius: 1.4).saturation(0.85)
                    SceneArt().mask(alignment: .leading) {
                        Rectangle().frame(width: g.size.width - x).offset(x: x)
                    }
                    Rectangle().fill(.white).frame(width: 2).shadow(color: .black.opacity(0.5), radius: 4).offset(x: x - 1)
                    Circle().fill(.white).frame(width: 28, height: 28).shadow(color: .black.opacity(0.4), radius: 4, y: 2)
                        .overlay(Text("‹ ›").auFont(11, .bold).foregroundStyle(AU.surface))
                        .offset(x: x - 14, y: g.size.height / 2 - 14)
                    HStack {
                        tag("L", left)
                        Spacer()
                        tag("R", right)
                    }
                    .padding(10)
                }
            }
        }
        .clipShape(RoundedRectangle(cornerRadius: 12))
        .overlay(RoundedRectangle(cornerRadius: 12).strokeBorder(AU.glassLine))
        .shadow(color: .black.opacity(0.45), radius: 20, y: 18)
    }

    private func tag(_ side: String, _ name: String) -> some View {
        HStack(spacing: 6) {
            Text(side).auFont(10.5, .semibold, mono: true).padding(.horizontal, 4)
                .background(RoundedRectangle(cornerRadius: 3).fill(.white.opacity(0.18)))
            Text(name).auFont(10.5, mono: true).lineLimit(1).fixedSize()
            Image(systemName: "chevron.down").auFont(7).opacity(0.8)
        }
        .foregroundStyle(.white)
        .padding(.vertical, 2).padding(.leading, 3).padding(.trailing, 8)
        .background(RoundedRectangle(cornerRadius: 5).fill(.black.opacity(0.6)))
        .overlay(RoundedRectangle(cornerRadius: 5).strokeBorder(.white.opacity(0.25)))
    }
}

/// compare.py `scene()`: a dusk sky, a sun, two ranges of hills and a tree.
private struct SceneArt: View {
    var body: some View {
        Canvas { ctx, size in
            let w = size.width, h = size.height
            ctx.fill(Path(CGRect(origin: .zero, size: size)),
                     with: .linearGradient(Gradient(stops: [
                        .init(color: Color(red: 0.965, green: 0.843, blue: 0.655), location: 0),
                        .init(color: Color(red: 0.953, green: 0.651, blue: 0.514), location: 0.38),
                        .init(color: Color(red: 0.471, green: 0.435, blue: 0.651), location: 0.70),
                     ]), startPoint: .zero, endPoint: CGPoint(x: 0, y: h)))
            let sun = w * 0.117
            ctx.drawLayer { l in
                l.addFilter(.shadow(color: Color(red: 1, green: 0.906, blue: 0.659), radius: sun * 0.5))
                l.fill(Path(ellipseIn: CGRect(x: w * 0.58, y: h * 0.16, width: sun, height: sun)),
                       with: .color(Color(red: 1, green: 0.961, blue: 0.839)))
            }
            func range(_ top: Double, _ points: [(Double, Double)], _ color: Color) {
                var p = Path()
                let y0 = h * (1 - top)
                p.move(to: CGPoint(x: 0, y: h))
                for (px, py) in points { p.addLine(to: CGPoint(x: w * px, y: y0 + h * top * py)) }
                p.addLine(to: CGPoint(x: w, y: h))
                p.closeSubpath()
                ctx.fill(p, with: .color(color))
            }
            range(0.46, [(0, 0.4), (0.18, 0.1), (0.34, 0.46), (0.52, 0.06), (0.70, 0.52), (0.86, 0.22), (1, 0.44)],
                  Color(red: 0.231, green: 0.231, blue: 0.427))
            let dark = Color(red: 0.133, green: 0.133, blue: 0.231)
            range(0.28, [(0, 0.3), (0.25, 0.6), (0.48, 0.2), (0.72, 0.55), (1, 0.25)], dark)
            ctx.fill(Path(CGRect(x: w * 0.22, y: h * 0.50, width: 3, height: h * 0.30)), with: .color(dark))
            ctx.fill(Path(ellipseIn: CGRect(x: w * 0.22 - 18, y: h * 0.56 - 38, width: 38, height: 38)), with: .color(dark))
        }
    }
}

private struct PlayBarIllustration: View {
    var body: some View {
        HStack(spacing: 10) {
            Image(systemName: "pause.fill").auFont(9).foregroundStyle(AU.text2)
                .frame(width: 24, height: 24)
                .background(RoundedRectangle(cornerRadius: 7).fill(AU.glass))
