/// The results panel as a sketch: one model with its numbers, the next one fading out.
private struct TestedModelsIllustration: View {
    @Environment(AppModel.self) private var model

    var body: some View {
        VStack(alignment: .leading, spacing: 10) {
            VStack(alignment: .leading, spacing: 6) {
                Text(model.t("nat.cmp.tested_models")).auFont(12.5, .semibold).foregroundStyle(AU.text)
                Capsule().fill(AU.trackSoft).frame(width: 170, height: 6)
            }
            card(model.t("mot.modello.cugan.label"), "R", clip: "3m", full: "~ 3h 43m", detail: (0.98, "197%"), noise: (0.66, "132%"))
            card(model.t("mot.modello.animevideov3.label"), "L", clip: "1m", full: "~ 1h 22m", detail: (0.82, "164%"), noise: (0.36, "71%"))
                .opacity(0.55)
        }
        .padding(.leading, 16)
        .overlay(alignment: .leading) { Rectangle().fill(AU.line).frame(width: 1) }
        .frame(maxHeight: .infinity, alignment: .top)
        .clipped()
        .overlay(alignment: .bottom) {
            LinearGradient(colors: [.clear, AU.surface], startPoint: .top, endPoint: .bottom).frame(height: 90)
        }
    }

    private func card(_ name: String, _ side: String, clip: String, full: String,
                      detail: (Double, String), noise: (Double, String)) -> some View {
        VStack(alignment: .leading, spacing: 10) {
            HStack {
                Text(name).auFont(12.5, .semibold).foregroundStyle(AU.text).lineLimit(1)
                Spacer()
                Text(side).auFont(10, .semibold, mono: true).padding(.horizontal, 5)
                    .background(RoundedRectangle(cornerRadius: 3).fill(AU.glass))
                    .overlay(RoundedRectangle(cornerRadius: 3).strokeBorder(AU.glassLine))
            }
            HStack(alignment: .top) {
                value(model.t("nat.cmp.this_clip"), clip)
                Spacer()
                value(model.t("nat.cmp.full_episode"), full)
                Spacer()
            }
            metric(model.t("nat.cmp.detail"), detail, AU.primary)
            metric(model.t("nat.cmp.noise"), noise, AU.text3)
            HStack(spacing: 6) {
                ForEach(0..<2, id: \.self) { _ in
                    RoundedRectangle(cornerRadius: 6).fill(AU.glass).frame(height: 22)
                        .overlay(RoundedRectangle(cornerRadius: 6).strokeBorder(AU.glassLine))
                }
            }
        }
        .padding(12)
        .background(RoundedRectangle(cornerRadius: 9).fill(AU.raised))
        .overlay(RoundedRectangle(cornerRadius: 9).strokeBorder(AU.chipLine))
    }

    private func value(_ label: String, _ v: String) -> some View {
        VStack(alignment: .leading, spacing: 3) {
            Text(label).auFont(11).foregroundStyle(AU.text3)
            Text(v).auFont(13, mono: true).foregroundStyle(AU.text)
        }
    }

    private func metric(_ label: String, _ m: (Double, String), _ color: Color) -> some View {
        VStack(spacing: 5) {
            HStack(alignment: .firstTextBaseline) {
                Text(label).auSmall()
                Spacer()
                Text(m.1).auFont(11, mono: true).foregroundStyle(AU.textCode)
            }
            GeometryReader { g in
                Capsule().fill(AU.trackSoft)
                    .overlay(alignment: .leading) { Capsule().fill(color).frame(width: g.size.width * m.0) }
                    .overlay { Rectangle().fill(AU.text3).frame(width: 1, height: 10) }
            }
            .frame(height: 4)
        }
    }
}

// MARK: - Step 3, Queue

/// Three rows drawn as placeholders: done, running (its fill and pieced bar
/// growing slowly from 14% to 78%), queued.
private struct QueueRowsIllustration: View {
    @Environment(AppModel.self) private var model

    var body: some View {
        VStack(spacing: 10) {
            row(lead: AnyView(Image(systemName: "checkmark").auFont(9, .semibold).foregroundStyle(AU.greenText)
                    .frame(width: 22, height: 22).background(Circle().fill(AU.greenBg)).overlay(Circle().strokeBorder(AU.greenLine))),
                chip: StatusChip(model.t("nat.chip.done"), tone: .green, symbol: "checkmark"),
                fill: AU.soft, line: AU.greenLine)
            live
            row(lead: AnyView(Circle().strokeBorder(AU.glassLine).frame(width: 22, height: 22)),
                chip: StatusChip(model.t("nat.chip.queued")), fill: .clear, line: AU.line, dim: true)
        }
    }

    private func names(_ dim: Bool = false) -> some View {
        VStack(alignment: .leading, spacing: 7) {
            Capsule().fill(AU.text3.opacity(dim ? 0.45 : 0.8)).frame(width: 150, height: 7)
            Capsule().fill(AU.text3.opacity(0.4)).frame(width: 96, height: 6)
        }
    }

    private func row(lead: AnyView, chip: StatusChip, fill: Color, line: Color, dim: Bool = false) -> some View {
        HStack(spacing: 14) {
            lead
            names(dim)
            Spacer()
            chip
        }
        .padding(.horizontal, 16)
        .frame(height: 50)
        .background(RoundedRectangle(cornerRadius: 10).fill(fill).background(RoundedRectangle(cornerRadius: 10).fill(AU.surface)))
        .overlay(RoundedRectangle(cornerRadius: 10).strokeBorder(line))
        .opacity(dim ? 0.7 : 1)
    }

    private var live: some View {
        TimelineView(.animation) { tl in
            // 9 s: grow from 14% to 78% over 80% of it, hold, then fade out; the next
            // round fades in from the start, instead of the bar jumping back.
            let phase = tl.date.timeIntervalSinceReferenceDate.truncatingRemainder(dividingBy: 9) / 9
            let eased = min(1, phase / 0.80)
            let progress = 0.14 + 0.64 * (eased < 0.5 ? 2 * eased * eased : 1 - pow(-2 * eased + 2, 2) / 2)
            let shown = phase < 0.06 ? phase / 0.06 : phase > 0.90 ? (1 - phase) / 0.10 : 1
            VStack(alignment: .leading, spacing: 12) {
                HStack(spacing: 14) {
                    Spinner(size: 22)
                    names()
                    Spacer()
                    StatusChip(model.t("nat.chip.in_progress"), tone: .accent)
                }
                // In the stacked block the four stages and the chip don't fit: three stages then.
                ViewThatFits(in: .horizontal) {
                    stagesLine(4)
                    stagesLine(3)
                }
                .padding(.leading, 36)
            }
            .padding(.horizontal, 16).padding(.top, 14).padding(.bottom, 18)
            .background(alignment: .leading) {
                GeometryReader { g in Rectangle().fill(AU.soft).frame(width: g.size.width * progress).opacity(shown) }
            }
            .overlay(alignment: .bottom) {
                GeometryReader { g in
                    ZStack(alignment: .leading) {
                        Rectangle().fill(AU.trackSoft)
                        Rectangle().fill(AU.primary).frame(width: g.size.width * progress).opacity(shown)
                        // The pieces: extraction, repeated frames, three chunks, assembly.
                        ForEach([0.05, 0.08, 0.38, 0.67, 0.96], id: \.self) { x in
                            Rectangle().fill(AU.surface).frame(width: 3).offset(x: g.size.width * x)
                        }
                    }
                }
                .frame(height: 4)
            }
            .background(RoundedRectangle(cornerRadius: 10).fill(AU.surface))
            .clipShape(RoundedRectangle(cornerRadius: 10))
            .overlay(RoundedRectangle(cornerRadius: 10).strokeBorder(AU.softLine))
        }
    }

    private func stagesLine(_ count: Int) -> some View {
        HStack(spacing: 10) {
            stageDots(count)
            Spacer(minLength: 10)
            StatusChip(model.t("nat.empty.repeated"), tone: .accent, symbol: "checkmark")
        }
    }

    private func stageDots(_ count: Int) -> some View {
        HStack(spacing: 10) {
            ForEach(Array([(0, 34.0), (0, 44), (1, 40), (2, 36)].suffix(count).enumerated()), id: \.offset) { i, s in
                if i > 0 { Text("→").auFont(11).foregroundStyle(AU.text3) }
                HStack(spacing: 6) {
                    Circle().fill(s.0 == 0 ? AU.green : s.0 == 1 ? AU.primary : AU.text3.opacity(0.6))
                        .frame(width: s.0 == 1 ? 10 : 8, height: s.0 == 1 ? 10 : 8)
                    Capsule().fill(AU.text3.opacity(0.5)).frame(width: s.1, height: 5)
                }
            }
        }
    }
}

/// Board E0c's note: spinner, how many videos are being analysed, a thin bar.
private struct AnalysingNote: View {
    @Environment(AppModel.self) private var model

    var body: some View {
        let a = model.activity
        let waiting = model.files.filter { $0.state == .analysing || $0.state == .queued }.count
        let total = max(1, a.running ? (a.total ?? waiting) : waiting)
        let index = min(total, max(1, a.index ?? 1))
        HStack(spacing: 10) {
            Spinner(size: 14)
            VStack(alignment: .leading, spacing: 7) {
                Text("\(Text(model.localizer.tn("nat.empty.analysing_title", total)).fontWeight(.semibold)) · \(model.t("nat.empty.analysing_text", ["i": index, "n": total]))")
                    .auFont(12.5)
                    .fixedSize(horizontal: false, vertical: true)
                AUBar(Double(index - 1) / Double(total), height: 3, fill: AU.primary, track: AU.softLine)
                    .frame(maxWidth: 420)
            }
            .frame(maxWidth: .infinity, alignment: .leading)
            Button(model.t("nat.empty.show_queue")) { model.tab = .queue }.auButton(.secondary, .small)
        }
        .foregroundStyle(AU.primaryText)
        .auBox(RoundedRectangle(cornerRadius: AU.Radius.field), fill: AU.soft, line: AU.softLine,
               padding: EdgeInsets(vertical: 12, horizontal: 14))
    }
}
